/* A track project: the source of a track, a folder such as art/tnfs-tracks/<id>/ (notes/dep59-track-editor-design.md §4.1).
 *
 *   project.ini   id, name, author, stem, art (the stage's FAM, relative to the project folder), redistributable
 *   trace.json    the centre line: its control points (x, z in units) and the verge width of its nodes
 *
 * The folder's build/ is regenerated by the editor (build.h); the editor writes nothing else in it. */
#ifndef TNFS_TRACK_EDITOR_PROJECT_H
#define TNFS_TRACK_EDITOR_PROJECT_H

#include "formats/mod_ini.h"
#include "formats/track_trace.h"

#include <stddef.h>

enum {
    PROJECT_TEXT_MAX = 128,
    PROJECT_POINTS_MAX = 2400,    /* a road of 599 segments has about this many control points at most; more are refused on load */
    PROJECT_START_POINTS = 6,     /* a new project is a straight of this many points */
    PROJECT_START_LENGTH = 200,   /* and this long, in units */
    PROJECT_PATH_MAX = 512,
    PROJECT_WIDTH_MIN = 8,        /* track_gen's layout range for a road's width (the verge byte) */
    PROJECT_WIDTH_MAX = 120
};

typedef struct {
    char id[MOD_INI_ID_MAX + 1];
    char name[PROJECT_TEXT_MAX];
    char author[PROJECT_TEXT_MAX];
    char stem[9];                 /* the piece's stem: 1..7 of A-Z 0-9, not AL, CL, CY or TR first */
    char art[PROJECT_PATH_MAX];   /* the stage's art, a FAM file: relative to the project folder, or absolute; "" is refused by the build */
    int redistributable;          /* the author's word on the art's licence (the editor writes no CD byte) */
} Project;

typedef struct {
    TracePoint *points;           /* malloc'd, `count` of them */
    int count;
    double width;                 /* the verge byte of every node, as track_gen takes it */
} Trace;

/* Reads the project in `dir` (its project.ini and trace.json). 1 with `out` and `trace` filled (the caller frees trace->points); 0 with
 * `why` (a sentence naming the file) otherwise. */
int project_open(const char *dir, Project *out, Trace *trace, char *why, size_t why_cap);

/* Creates the files of a new project in `dir` where they are missing: project.ini with `id`, and trace.json as a straight. Existing files are
 * kept. `generic_art` is the editor's own GENERIC.FAM (art.h), or NULL when there is none: a new project gets a copy of it as GENERIC.FAM and
 * art=GENERIC.FAM; a project of the first Studio, whose art= points at ../generic-straight/GENERIC.FAM (a path only the source tree had) and
 * is not readable, gets the copy and the line rewritten. Any other art= is left as it is. 1 on success, 0 with `why`. */
int project_create(const char *dir, const char *id, const char *generic_art, char *why, size_t why_cap);

/* Writes trace.json of `dir` (through a temporary file, then renamed). 1 on success, 0 with `why`. */
int project_save_trace(const char *dir, const Trace *trace, char *why, size_t why_cap);

#endif
